package main

import (
	"bytes"
	"time"
	tea "github.com/charmbracelet/bubbletea"
)

type model struct{}

func (m model) Init() tea.Cmd {
	return nil
}

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	return m, tea.Quit
}

func (m model) View() string {
	return "test"
}

func main() {
	// Create a new program
	p := tea.NewProgram(model{}, tea.WithInput(bytes.NewReader(nil)), tea.WithOutput(bytes.NewBuffer(nil)))

	// Start a goroutine that calls Wait() immediately
	done := make(chan bool)
	go func() {
		p.Wait()
		done <- true
	}()

	// Give the goroutine a moment to start waiting
	time.Sleep(100 * time.Millisecond)

	// Run the program
	p.Run()

	// Wait for Wait() to return
	select {
	case <-done:
		// Success!
	case <-time.After(1 * time.Second):
		// Failure - Wait() blocked forever
		panic("Wait() blocked forever - race condition still exists!")
	}
}
EOF
